using BuergerbusAPI.Data; using BuergerbusAPI.Models; using Microsoft.EntityFrameworkCore; using System.Security.Cryptography; using System.Text;
namespace BuergerbusAPI.Services;
public sealed class RefreshSessionService(AppDbContext db)
{
 private const string CookieName="buergerbus_refresh"; private static readonly TimeSpan Lifetime=TimeSpan.FromDays(14);
 public async Task<(RefreshSession Session,string Token)> CreateAsync(Benutzer user,HttpContext context,CancellationToken ct=default){var token=Convert.ToBase64String(RandomNumberGenerator.GetBytes(32)).Replace('+','-').Replace('/','_').TrimEnd('=');var session=new RefreshSession{Id=Guid.NewGuid(),UserId=user.Id,TokenHash=Hash(token),CreatedAtUtc=DateTime.UtcNow,ExpiresAtUtc=DateTime.UtcNow.Add(Lifetime),AuthVersion=user.AuthVersion,UserAgentHash=HashOptional(context.Request.Headers.UserAgent),IpAddressHash=HashOptional(context.Connection.RemoteIpAddress?.ToString())};db.RefreshSessions.Add(session);await db.SaveChangesAsync(ct);return(session,token);}
 public async Task<(Benutzer User,RefreshSession Old,string Token,RefreshSession New)?> RotateAsync(string? token,HttpContext context,CancellationToken ct=default){if(string.IsNullOrEmpty(token))return null;var old=await db.RefreshSessions.Include(x=>x.Benutzer).FirstOrDefaultAsync(x=>x.TokenHash==Hash(token),ct);if(old is null)return null;if(old.RevokedAtUtc.HasValue){await RevokeAllAsync(old.UserId,"reuse_detected",ct);return null;}var user=old.Benutzer;if(user is null||old.ExpiresAtUtc<=DateTime.UtcNow||!user.Aktiv||old.AuthVersion!=user.AuthVersion){if(!old.RevokedAtUtc.HasValue){old.RevokedAtUtc=DateTime.UtcNow;old.RevokedReason="invalid";await db.SaveChangesAsync(ct);}return null;}var created=await CreateAsync(user,context,ct);old.RevokedAtUtc=DateTime.UtcNow;old.LastUsedAtUtc=DateTime.UtcNow;old.ReplacedBySessionId=created.Session.Id;old.RevokedReason="rotated";await db.SaveChangesAsync(ct);return(user,old,created.Token,created.Session);}
 public async Task RevokeAsync(string? token,string reason,CancellationToken ct=default){if(string.IsNullOrEmpty(token))return;var session=await db.RefreshSessions.FirstOrDefaultAsync(x=>x.TokenHash==Hash(token),ct);if(session is not null&&!session.RevokedAtUtc.HasValue){session.RevokedAtUtc=DateTime.UtcNow;session.RevokedReason=reason;await db.SaveChangesAsync(ct);}}
 public async Task RevokeAllAsync(int userId,string reason,CancellationToken ct=default){var active=await db.RefreshSessions.Where(x=>x.UserId==userId&&!x.RevokedAtUtc.HasValue).ToListAsync(ct);foreach(var x in active){x.RevokedAtUtc=DateTime.UtcNow;x.RevokedReason=reason;}await db.SaveChangesAsync(ct);}
 public void WriteCookie(HttpResponse response,string token,DateTime expires)=>response.Cookies.Append(CookieName,token,new CookieOptions{HttpOnly=true,Secure=true,SameSite=SameSiteMode.Strict,Path="/api/v1/auth",Expires=expires,IsEssential=true}); public void DeleteCookie(HttpResponse response)=>response.Cookies.Delete(CookieName,new CookieOptions{HttpOnly=true,Secure=true,SameSite=SameSiteMode.Strict,Path="/api/v1/auth",IsEssential=true}); public static string? ReadCookie(HttpRequest request)=>request.Cookies[CookieName];
 private static string Hash(string value)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value))); private static string? HashOptional(string? value)=>string.IsNullOrEmpty(value)?null:Hash(value);
}
